*adjusts reading glasses and sets down a thick folder*

Let me tell you what keeps me up at night about CLI tools: they're attack surfaces. Every argument, every file path, every edge case is a potential liability. Here's what a thorough deposition—I mean, test suite—looks like:

```go
package main

import (
	"bytes"
	"os"
	"path/filepath"
	"testing"
)

func TestCLI_ArgumentParsing(t *testing.T) {
	tests := []struct {
		name       string
		args       []string
		wantCode   int
		wantStderr string
	}{
		{"no args shows usage", []string{}, 2, "Usage:"},
		{"unknown command", []string{"bogus"}, 2, "unknown command"},
		{"get without key", []string{"get"}, 2, "requires a key"},
		{"set without value", []string{"set", "key"}, 2, "requires key and value"},
		{"delete without key", []string{"delete"}, 2, "requires a key"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
			cli := NewCLI(stdout, stderr, t.TempDir())

			code := cli.Run(tt.args)

			if code != tt.wantCode {
				t.Errorf("exit code = %d, want %d", code, tt.wantCode)
			}
			if !bytes.Contains(stderr.Bytes(), []byte(tt.wantStderr)) {
				t.Errorf("stderr = %q, want containing %q", stderr.String(), tt.wantStderr)
			}
		})
	}
}

func TestCLI_InitCommand(t *testing.T) {
	t.Run("creates config file", func(t *testing.T) {
		stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
		dir := t.TempDir()
		cli := NewCLI(stdout, stderr, dir)

		code := cli.Run([]string{"init"})

		if code != 0 {
			t.Fatalf("exit code = %d, stderr = %s", code, stderr.String())
		}
		if _, err := os.Stat(filepath.Join(dir, "config.yaml")); err != nil {
			t.Error("config file not created")
		}
	})

	t.Run("fails if file exists", func(t *testing.T) {
		stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
		dir := t.TempDir()
		os.WriteFile(filepath.Join(dir, "config.yaml"), []byte("existing"), 0644)
		cli := NewCLI(stdout, stderr, dir)

		code := cli.Run([]string{"init"})

		if code != 1 {
			t.Errorf("expected error exit code, got %d", code)
		}
	})
}

func TestCLI_GetSetDelete(t *testing.T) {
	stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
	dir := t.TempDir()
	cli := NewCLI(stdout, stderr, dir)

	// Set creates config if missing
	if code := cli.Run([]string{"set", "database.host", "localhost"}); code != 0 {
		t.Fatalf("set failed: %s", stderr.String())
	}

	// Get retrieves value
	stdout.Reset()
	if code := cli.Run([]string{"get", "database.host"}); code != 0 {
		t.Fatalf("get failed: %s", stderr.String())
	}
	if got := stdout.String(); got != "localhost\n" {
		t.Errorf("get = %q, want localhost", got)
	}

	// Delete removes key
	stdout.Reset()
	cli.Run([]string{"delete", "database.host"})
	stderr.Reset()
	if code := cli.Run([]string{"get", "database.host"}); code != 1 {
		t.Error("expected key not found after delete")
	}
}

func TestCLI_OutputFormats(t *testing.T) {
	dir := t.TempDir()
	configPath := filepath.Join(dir, "config.yaml")
	os.WriteFile(configPath, []byte("key: value\n"), 0644)

	formats := []struct {
		format   string
		contains string
	}{
		{"json", `"key"`},
		{"yaml", "key:"},
		{"text", "key:"},
	}

	for _, tt := range formats {
		t.Run(tt.format, func(t *testing.T) {
			stdout := &bytes.Buffer{}
			cli := NewCLI(stdout, &bytes.Buffer{}, dir)
			cli.Run([]string{"--format", tt.format, "list"})

			if !bytes.Contains(stdout.Bytes(), []byte(tt.contains)) {
				t.Errorf("output = %q, want containing %q", stdout.String(), tt.contains)
			}
		})
	}
}

func TestCLI_InvalidYAML(t *testing.T) {
	dir := t.TempDir()
	configPath := filepath.Join(dir, "config.yaml")
	os.WriteFile(configPath, []byte("invalid: yaml: content: ["), 0644)

	stderr := &bytes.Buffer{}
	cli := NewCLI(&bytes.Buffer{}, stderr, dir)

	code := cli.Run([]string{"validate"})

	if code != 1 {
		t.Error("expected failure for invalid YAML")
	}
	if !bytes.Contains(stderr.Bytes(), []byte("invalid YAML")) {
		t.Errorf("stderr = %q, want YAML error", stderr.String())
	}
}

func TestCLI_FilePermissions(t *testing.T) {
	if os.Getuid() == 0 {
		t.Skip("cannot test permissions as root")
	}

	dir := t.TempDir()
	os.Chmod(dir, 0444)
	defer os.Chmod(dir, 0755)

	stderr := &bytes.Buffer{}
	cli := NewCLI(&bytes.Buffer{}, stderr, dir)

	code := cli.Run([]string{"init"})

	if code != 1 {
		t.Error("expected failure for read-only directory")
	}
}
```

*taps pen on desk*

This covers the obvious exposures. But I'd want additional tests for path traversal attacks, concurrent file access, and environment variable injection before I'd sign off on production deployment.
